import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

void main() {
  const nuevos = ['app', 'core', 'features', 'layout', 'theme'];
  const viejos = [
    'components',
    'configs',
    'cubits',
    'models',
    'pages',
    'router',
    'services',
  ];

  // firebase_options.dart is generated by `flutterfire configure` at this
  // fixed path (see firebase.json).
  test('S1.1 lib contains only the new top-level dirs plus main.dart and '
      'firebase_options.dart', () {
    final entradas = Directory('lib')
        .listSync()
        .map((e) => e.uri.pathSegments.where((s) => s.isNotEmpty).last)
        .toSet();
    expect(entradas, {...nuevos, 'main.dart', 'firebase_options.dart'});
  });

  for (final dir in viejos) {
    test('S1.1 old dir lib/$dir is absent', () {
      expect(Directory('lib/$dir').existsSync(), isFalse);
    });
  }
}
